// GANTI dengan chat id Telegram owner (angka). Kirim pesan apa saja ke bot: bot membalas dengan chat id kamu.
const OWNER = '513805302';

const s = $getWorkflowStaticData('global');
s.queue = s.queue || []; s.seq = s.seq || 0;
const u = $input.first().json;
const out = { chatId: null, text: null, queryId: null };
const push = (id, action, note = '', photos = []) => { s.seq += 1; s.queue.push({ seq: s.seq, id: Number(id), action, note, photos, ts: new Date().toISOString() }); };

// foto contoh desain: disimpan dulu max 15 menit, ikut ke revisi/pesan berikutnya (max 4)
const now = Date.now();
s.photos = (s.photos || []).filter((p) => now - p.ts < 15 * 60 * 1000);
const takePhotos = () => { const ids = s.photos.map((p) => p.id).slice(-4); s.photos = []; return ids; };

if (u.callback_query) {
  const q = u.callback_query;
  out.queryId = q.id;
  out.chatId = String(q.message.chat.id);
  if (String(q.from.id) !== OWNER) {
    out.text = 'Bot ini khusus owner Zataa.';
  } else {
    const [act, id] = String(q.data || '').split(':');
    if (act === 'ok') { push(id, 'approve'); s.waiting = null; out.text = `✅ #${id} di-approve. Masuk antrian tayang.`; }
    else if (act === 'no') { push(id, 'reject'); s.waiting = null; out.text = `❌ #${id} ditolak.`; }
    else if (act === 'rev') { s.waiting = id; out.text = `✏️ Ketik catatan revisi buat #${id} (boleh kirim foto contoh desain juga):`; }
    else if (act === 'boost') { push(id, 'boost'); out.text = `🚀 Boost B${id} disetujui. Fahriah lagi pasang iklannya.`; }
    else if (act === 'skip') { push(id, 'boost_skip'); out.text = `👌 Boost B${id} dilewati.`; }
    else if (act === 'plan') { push(id, 'plan_approve'); s.waiting = null; out.text = '✅ Plan minggu ini di-approve. Tim mulai produksi!'; }
    else if (act === 'planrev') { s.waiting = `plan:${id}`; out.text = '✏️ Ketik catatan revisi plan (boleh kirim foto contoh juga):'; }
    else if (act === 'idea') { push(id, 'idea_approve', String(id)); out.text = '💡 Ide di-approve, tim langsung produksi!'; }
    else if (act === 'ideas') { const ids = String(id).split('-'); push(ids[0], 'idea_approve', ids.join(',')); out.text = `💡 ${ids.length} ide di-approve, gas!`; }
    else if (act === 'ideaskip') { push(id, 'idea_skip'); out.text = '🔄 Semua ide ditolak. Tim cari ide baru, nanti Andre kirim lagi.'; }
    else if (act === 'pricepromo') { push(id, 'price_promo'); out.text = '🎨 Siap! Tim bikin konten promo harga.'; }
  }
} else if (u.message) {
  const m = u.message;
  out.chatId = String(m.chat.id);
  const txt = String(m.text || m.caption || '').trim();
  const photo = m.photo?.length ? m.photo[m.photo.length - 1].file_id
    : (m.document && String(m.document.mime_type || '').startsWith('image/')) ? m.document.file_id : null;
  if (String(m.from.id) !== OWNER) {
    out.text = `Chat ID kamu: ${m.chat.id}\nMasukkan angka ini ke node "Proses" (OWNER) dan ke .env (TELEGRAM_CHAT_ID).`;
  } else {
    if (photo) s.photos.push({ id: photo, ts: now });
    // balas langsung ke pesan konten (#id) = revisi (kecuali pesan usulan boost)
    const rtext = String(m.reply_to_message?.text || m.reply_to_message?.caption || '');
    const planReply = rtext.match(/Plan C(\d+)/);
    const replied = rtext.includes('Usulan boost') || rtext.includes('Ide konten tambahan') || /harga di web berubah/i.test(rtext) ? null : rtext.match(/#(\d+)/);
    const id = planReply ? `plan:${planReply[1]}` : replied ? replied[1] : s.waiting;
    const isPlan = String(id || '').startsWith('plan:');
    if (photo && !txt) {
      // foto tanpa teks: tunggu catatannya (album dikirim per foto, cukup balas sekali)
      out.text = m.media_group_id && s.photos.length > 1 ? `📷 Foto ke-${s.photos.length} diterima.` : `📷 Contoh desain diterima${id ? ` buat #${id}` : ''}. Sekarang ketik catatannya ya bos.`;
    } else if (txt && !txt.startsWith('/') && isPlan) {
      const photos = takePhotos();
      push(String(id).slice(5), 'plan_revision', txt, photos);
      s.waiting = null;
      out.text = `📝 Revisi plan dicatat${photos.length ? ` (+${photos.length} foto)` : ''}. Aprista lagi benerin, nanti dikirim ulang.`;
    } else if (txt && !txt.startsWith('/') && id) {
      const photos = takePhotos();
      push(id, 'revision', txt, photos);
      s.waiting = null;
      out.text = `📝 Revisi #${id} dicatat${photos.length ? ` (+${photos.length} foto contoh)` : ''}:\n«${txt}»\nTim lagi ngerjain, nanti dikirim ulang ke sini.`;
    } else if (txt && !txt.startsWith('/')) {
      // pesan bebas → tim (tanya status / kasih tugas)
      const photos = takePhotos();
      push(0, 'chat', txt, photos);
      // tanpa balasan "diterima": Owner langsung nunggu jawaban pegawainya
    } else {
      out.text = 'Halo bos 👋\n• Konten siap dikirim ke sini: ✅ Approve, ✏️ Revisi, ❌ Tolak (atau reply pesannya buat revisi).\n• Boleh kirim foto contoh desain + catatannya.\n• Chat bebas buat kasih tugas, misal: "harga diamond ML ada update, bikinin desain, langsung upload".\n• Tanya "lagi pada ngapain" buat lihat kegiatan tim.';
    }
  }
}
s.queue = s.queue.slice(-300);
// nggak ada yang perlu dibalas (chat bebas) → berhenti di sini, node Telegram berikutnya nggak jalan
if (!out.text && !out.queryId) return [];
return [{ json: out }];

// PC mengirim ?ack=<nomor terakhir yang sudah diproses>; yang sudah di-ack dibuang
const s = $getWorkflowStaticData('global');
s.queue = s.queue || [];
const ack = Number($input.first().json.query?.ack || 0);
s.queue = s.queue.filter((d) => d.seq > ack);
return [{ json: { decisions: s.queue } }];
